const createdOrder = pm.response.json();

pm.test("Création réussie - HTTP 201", function () {
    pm.response.to.have.status(201);
});

pm.test("Description correcte", function () {
    pm.expect(createdOrder.description)
        .to.eql(pm.environment.get("description"));
});

pm.test("Speciality correcte", function () {
    pm.expect(createdOrder.speciality)
        .to.eql(pm.environment.get("speciality"));
});

pm.test("Priority correcte", function () {
    pm.expect(createdOrder.priority)
        .to.eql(pm.environment.get("priority"));
});

pm.test("Identifiant correctement généré", function () {
    pm.expect(createdOrder.id).to.exist;
});

pm.environment.set("workOrderId", createdOrder.id);

pm.test("Affectation - HTTP 200", function () {
    pm.response.to.have.status(200);
});

const assignedOrder = pm.response.json();
const requestData = JSON.parse(pm.request.body.raw);

pm.test("Technicien correctement affecté", function () {
    pm.expect(assignedOrder.technician)
        .to.eql(requestData.technician.trim());
});

pm.test("Statut ASSIGNED", function () {
    pm.expect(assignedOrder.status).to.eql("ASSIGNED");
});

pm.test("Historique correctement mis à jour", function () {
    pm.expect(assignedOrder.history)
        .to.include("NEW");
    pm.expect(assignedOrder.history)
        .to.include(assignedOrder.status);
});

const updatedOrder = pm.response.json();
const requestData = JSON.parse(pm.request.body.raw);

pm.test("Démarrage réussi - HTTP 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Statut correctement modifié", function () {
    pm.expect(updatedOrder.status).to.eql(requestData.status);
});

pm.test("Technicien conservé", function () {
    pm.expect(updatedOrder.technician).to.be.a("string").and.not.empty;
});

pm.test("Historique mis à jour", function () {
    pm.expect(updatedOrder.history)
        .to.include(requestData.status);
});

const completedOrder = pm.response.json();
const requestData = JSON.parse(pm.request.body.raw);

pm.test("Clôture réussie - HTTP 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Statut correctement modifié", function () {
    pm.expect(completedOrder.status).to.eql(requestData.status);
});

pm.test("Technicien conservé", function () {
    pm.expect(completedOrder.technician).to.be.a("string").and.not.empty;
});

pm.test("Historique complet", function () {
    pm.expect(completedOrder.history)
        .to.include("NEW")
        .and.to.include("ASSIGNED")
        .and.to.include("IN_PROGRESS")
        .and.to.include(requestData.status);
});

pm.test("Consultation réussie - HTTP 200", function () {
    pm.response.to.have.status(200);
});

const consultedOrder = pm.response.json();

pm.test("Identifiant correct", function () {
    pm.expect(consultedOrder.id).to.eql(
        Number(pm.environment.get("workOrderId"))
    );
});

pm.test("Technicien correctement affecté", function () {
    pm.expect(consultedOrder.technician)
        .to.be.a("string")
        .and.not.empty;
});

pm.test("Statut final correctement enregistré", function () {
    pm.expect(consultedOrder.status).to.eql("COMPLETED");
});

pm.test("Historique complet", function () {
    pm.expect(consultedOrder.history).to.eql([
        "NEW",
        "ASSIGNED",
        "IN_PROGRESS",
        "COMPLETED"
    ]);
});

pm.test("Transition interdite - HTTP 409", function () {
    pm.response.to.have.status(409);
});

const errorData = pm.response.json();

pm.test("Message d'erreur présent", function () {
    pm.expect(errorData.message).to.include("Transition impossible");
});
